<template>
  <section class="records-page">
    <div class="page-header"><div><div class="eyebrow">TRUST EXCHANGES</div><h2>Verifications</h2><p>Presentation exchanges and the credential attributes revealed during verification.</p></div><div class="header-actions"><span class="mode-chip"><i></i>{{ demoMode ? 'Demo data' : 'Live gateway' }}</span><span class="count-badge">{{ filtered.length }} records</span></div></div>
    <div class="stat-grid"><div class="stat-card"><span>Total presentations</span><strong>{{ press.length }}</strong><small>Verification exchanges</small></div><div class="stat-card success"><span>Verified</span><strong>{{ verifiedCount }}</strong><small>{{ verificationRate }}% verified</small></div><div class="stat-card warning"><span>Review queue</span><strong>{{ press.length - verifiedCount }}</strong><small>Needs investigation</small></div><div class="stat-card"><span>Showing</span><strong>{{ paged.length }}</strong><small>Page {{ page }} of {{ pageCount }}</small></div></div>
    <div class="toolbar-panel"><div class="search-wrap"><v-icon name="fa-search" /><input v-model="query" placeholder="Search thread, exchange, role…" /></div><select v-model="status"><option value="all">All results</option><option value="verified">Verified</option><option value="review">Needs review</option></select><select v-model="sortBy"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="role">Role</option></select><button class="clear-button" v-if="query || status !== 'all' || sortBy !== 'newest'" @click="resetFilters"><v-icon name="fa-times" /> Clear</button><div class="view-switch"><button :class="{active:viewMode==='grid'}" title="Grid view" @click="viewMode='grid'"><v-icon name="fa-th-large" /></button><button :class="{active:viewMode==='table'}" title="Table view" @click="viewMode='table'"><v-icon name="fa-list" /></button></div></div>
    <div v-if="viewMode === 'grid'" class="card-container"><p class="placeholder" v-if="!paged.length">No verifications match your filters.</p><PresentationCard v-for="pres in paged" :key="pres.thread_id" :pres="pres" /></div>
    <div v-else class="table-shell"><table><thead><tr><th>Thread</th><th>Exchange</th><th>Role</th><th>Created</th><th>Updated</th><th>Result</th><th>State</th></tr></thead><tbody><tr v-for="pres in paged" :key="pres.thread_id"><td><strong>{{ pres.thread_id }}</strong></td><td>{{ exchangeId(pres) }}</td><td><span class="role-pill"><v-icon name="fa-user-shield" /> {{ pres.role || 'Not available' }}</span></td><td>{{ formatDate(pres.created_at) }}</td><td>{{ formatDate(pres.updated_at) }}</td><td class="failure-cell"><strong>{{ failureFor(pres).title }}</strong><small>{{ failureFor(pres).code || 'PASS' }}</small></td><td><span class="table-status" :class="statusOf(pres)"><i></i>{{ labelOf(pres) }}</span></td></tr></tbody></table><p class="placeholder" v-if="!paged.length">No verifications match your filters.</p></div>
    <div class="pagination" v-if="filtered.length"><span>Showing {{ start + 1 }}–{{ Math.min(start + pageSize, filtered.length) }} of {{ filtered.length }}</span><div><button :disabled="page===1" @click="page--"><v-icon name="fa-chevron-left" /></button><button v-for="n in pageCount" :key="n" :class="{active:page===n}" @click="page=n">{{ n }}</button><button :disabled="page===pageCount" @click="page++"><v-icon name="fa-chevron-right" /></button></div></div>
  </section>
</template>
<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import axios from 'axios'
import PresentationCard from './PresentationCard.vue'
import { demoPresentations } from '../demoData'
import { demoMode } from '../dataMode'
import { normalizeVerificationRecord } from '../failures/failureModel.js'
const press=ref([]),query=ref(''),status=ref('all'),sortBy=ref('newest'),viewMode=ref('grid'),page=ref(1),pageSize=9
const failureFor = pres => normalizeVerificationRecord(pres).failure
const statusOf = pres => failureFor(pres).status === 'passed' ? 'pass' : failureFor(pres).status === 'pending' ? 'pending' : 'review'
const labelOf = pres => statusOf(pres) === 'pass' ? 'Verified' : statusOf(pres) === 'pending' ? 'Pending' : 'Needs review'
const exchangeId = p => p?.by_format?.pres_request?.indy?.requested_attributes?.attr_data_exchange_id?.restrictions?.[0]?.['attr::data_exchange_id::value'] || '—'
const filtered=computed(()=>press.value.filter(p=>{const failure = failureFor(p); const text=`${p.thread_id||''} ${exchangeId(p)} ${p.role||''} ${failure.title} ${failure.code||''}`.toLowerCase();const state = statusOf(p);return text.includes(query.value.toLowerCase())&&(status.value==='all'||(status.value==='verified'?state === 'pass':state !== 'pass'))}).sort((a,b)=>{if(sortBy.value==='role')return String(a.role).localeCompare(String(b.role));const d=sortBy.value==='oldest'?1:-1;return d*(new Date(a.created_at||0)-new Date(b.created_at||0))}))
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/pageSize))),start=computed(()=> (page.value-1)*pageSize),paged=computed(()=>filtered.value.slice(start.value,start.value+pageSize)),verifiedCount=computed(()=>press.value.filter(p=>statusOf(p) === 'pass').length),verificationRate=computed(()=>press.value.length?Math.round(verifiedCount.value/press.value.length*100):0)
watch([query,status,sortBy],()=>page.value=1);watch(pageCount,n=>{if(page.value>n)page.value=n});function resetFilters(){query.value='';status.value='all';sortBy.value='newest'};function formatDate(v){return v?new Date(v).toLocaleString([],{dateStyle:'medium',timeStyle:'short'}):'—'}
async function loadPresentations(){if(demoMode.value){press.value=demoPresentations;return}try{const r=await axios.get('/api/info/presentations');press.value=Array.isArray(r.data)?r.data:[]}catch{press.value=[]}}onMounted(loadPresentations);watch(demoMode,loadPresentations)
</script>
<style scoped>
