ng:2px;border:1px solid #dbe3ec;border-radius:8px;background:#fff}.view-switch button,.pagination button{display:grid;place-items:center;min-width:29px;height:29px;padding:0;border:0;border-radius:6px;color:#94a3b8;background:transparent;font-size:.72rem;cursor:pointer}.view-switch button.active,.view-switch button:hover,.pagination button.active{color:#0e7490;background:#cffafe}.card-container{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.table-shell{overflow:auto;border:1px solid #e2e8f0;border-radius:12px;background:#fff;box-shadow:0 4px 18px rgba(15,23,42,.04)}table{width:100%;border-collapse:collapse;text-align:left;font-size:.75rem}th{padding:13px 15px;color:#64748b;background:#f8fafc;border-bottom:1px solid #e2e8f0;font-size:.65rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase}td{padding:14px 15px;color:#475569;border-bottom:1px solid #f1f5f9;white-space:nowrap}tbody tr:hover{background:#f8fafc}td strong,td small{display:block}td strong{color:#334155}td small{margin-top:3px;color:#94a3b8;font-size:.65rem}.role-pill{display:inline-flex;align-items:center;gap:6px;color:#475569}.table-status{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;font-weight:700}.table-status i{width:6px;height:6px;border-radius:50%}.table-status.pass{color:#15803d;background:#f0fdf4}.table-status.pass i{background:#22c55e}.table-status.review{color:#b45309;background:#fffbeb}.table-status.review i{background:#f59e0b}.pagination{display:flex;align-items:center;justify-content:space-between;margin-top:14px;color:#64748b;font-size:.7rem}.pagination>div{display:flex;gap:3px}.pagination button:disabled{opacity:.35;cursor:not-allowed}.placeholder{grid-column:1/-1;margin:0;padding:42px;text-align:center;color:#94a3b8;border:1px dashed #cbd5e1;border-radius:12px;background:#fff}@media(max-width:1200px){.card-container{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:800px){.page-header,.toolbar-panel{align